CREATE TABLE character_lore_row(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,boundary TEXT NOT NULL,ordinal INTEGER NOT NULL,native_field TEXT NOT NULL,native_value TEXT NOT NULL,source_path TEXT NOT NULL,pointer TEXT NOT NULL,raw_json TEXT NOT NULL,UNIQUE(source_path,ordinal)) WITHOUT ROWID;
CREATE TABLE character_lore_reuse(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,boundary TEXT NOT NULL,source_path TEXT NOT NULL,ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,target_family TEXT NOT NULL,target_contract TEXT NOT NULL,target_run TEXT NOT NULL,target_occurrence_id TEXT NOT NULL,UNIQUE(source_path,ordinal)) WITHOUT ROWID;
CREATE TABLE character_lore_reuse_slot(id TEXT PRIMARY KEY,reuse_id TEXT NOT NULL REFERENCES character_lore_reuse(id),field TEXT NOT NULL,locale TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous')),candidate_count INTEGER NOT NULL CHECK(candidate_count>=0),target_owner_occurrence_id TEXT NOT NULL,target_resolution_occurrence_id TEXT NOT NULL,UNIQUE(reuse_id,field,locale)) WITHOUT ROWID;
CREATE TABLE character_lore_reuse_relation(id TEXT PRIMARY KEY,reuse_id TEXT NOT NULL REFERENCES character_lore_reuse(id),kind TEXT NOT NULL,source_pointer TEXT NOT NULL,raw_value TEXT NOT NULL,target_namespace TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous','mapping_unresolved')),candidate_count INTEGER NOT NULL CHECK(candidate_count>=0),search_complete INTEGER NOT NULL CHECK(search_complete IN (0,1)),historical_relation_occurrence_id TEXT,UNIQUE(reuse_id,kind,source_pointer)) WITHOUT ROWID;
CREATE TABLE character_lore_reuse_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES character_lore_reuse_relation(id),target_source_path TEXT NOT NULL,target_pointer TEXT NOT NULL,target_native_value TEXT NOT NULL,target_family TEXT NOT NULL,target_contract TEXT NOT NULL,target_run TEXT NOT NULL,target_occurrence_id TEXT NOT NULL,UNIQUE(relation_id,target_source_path,target_pointer,target_occurrence_id)) WITHOUT ROWID;
CREATE TABLE character_lore_slot(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES character_lore_row(id),field TEXT NOT NULL,locale TEXT NOT NULL,raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous')),UNIQUE(row_id,field,locale)) WITHOUT ROWID;
CREATE TABLE character_lore_text(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL REFERENCES character_lore_slot(id),source_path TEXT NOT NULL,pair_ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,raw_text TEXT NOT NULL,UNIQUE(slot_id,source_path,pair_ordinal)) WITHOUT ROWID;
CREATE TABLE character_lore_relation(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES character_lore_row(id),kind TEXT NOT NULL,source_pointer TEXT NOT NULL,raw_value TEXT NOT NULL,target_namespace TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous','mapping_unresolved')),candidate_count INTEGER NOT NULL CHECK(candidate_count>=0),search_complete INTEGER NOT NULL CHECK(search_complete IN (0,1)),UNIQUE(row_id,kind,source_pointer)) WITHOUT ROWID;
CREATE TABLE character_lore_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES character_lore_relation(id),target_source_path TEXT NOT NULL,target_pointer TEXT NOT NULL,target_native_value TEXT NOT NULL,target_family TEXT NOT NULL,target_contract TEXT NOT NULL,target_run TEXT NOT NULL,target_occurrence_id TEXT NOT NULL,UNIQUE(relation_id,target_source_path,target_pointer,target_occurrence_id)) WITHOUT ROWID;
CREATE TABLE character_lore_navigation_anchor(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,avatar_id TEXT NOT NULL,source_path TEXT NOT NULL,source_pointer TEXT NOT NULL,target_contract TEXT NOT NULL,target_run TEXT NOT NULL,target_occurrence_id TEXT NOT NULL,UNIQUE(source_path,source_pointer)) WITHOUT ROWID;
CREATE TABLE character_lore_navigation_edge(id TEXT PRIMARY KEY,anchor_id TEXT NOT NULL REFERENCES character_lore_navigation_anchor(id),kind TEXT NOT NULL,target_family TEXT NOT NULL,target_contract TEXT NOT NULL,target_run TEXT NOT NULL,target_occurrence_id TEXT NOT NULL,source_relation_id TEXT NOT NULL,UNIQUE(anchor_id,kind,target_family,target_run,target_occurrence_id,source_relation_id)) WITHOUT ROWID;
CREATE TABLE character_lore_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX character_lore_slot_parent ON character_lore_slot(row_id);
CREATE INDEX character_lore_reuse_slot_parent ON character_lore_reuse_slot(reuse_id);
CREATE INDEX character_lore_reuse_relation_parent ON character_lore_reuse_relation(reuse_id);
CREATE INDEX character_lore_reuse_candidate_parent ON character_lore_reuse_candidate(relation_id);
CREATE INDEX character_lore_text_slot ON character_lore_text(slot_id);
CREATE INDEX character_lore_relation_parent ON character_lore_relation(row_id);
CREATE INDEX character_lore_candidate_relation ON character_lore_candidate(relation_id);
CREATE INDEX character_lore_navigation_avatar ON character_lore_navigation_anchor(avatar_id);
CREATE INDEX character_lore_navigation_edge_parent ON character_lore_navigation_edge(anchor_id,kind,id);
CREATE INDEX character_lore_text_literal ON character_lore_text(raw_text);
CREATE TRIGGER character_lore_row_i BEFORE INSERT ON character_lore_row WHEN EXISTS(SELECT 1 FROM character_lore_row WHERE id=NEW.id OR(source_path=NEW.source_path AND ordinal=NEW.ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_i BEFORE INSERT ON character_lore_reuse WHEN EXISTS(SELECT 1 FROM character_lore_reuse WHERE id=NEW.id OR(source_path=NEW.source_path AND ordinal=NEW.ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_slot_i BEFORE INSERT ON character_lore_reuse_slot WHEN EXISTS(SELECT 1 FROM character_lore_reuse_slot WHERE id=NEW.id OR(reuse_id=NEW.reuse_id AND field=NEW.field AND locale=NEW.locale)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_relation_i BEFORE INSERT ON character_lore_reuse_relation WHEN EXISTS(SELECT 1 FROM character_lore_reuse_relation WHERE id=NEW.id OR(reuse_id=NEW.reuse_id AND kind=NEW.kind AND source_pointer=NEW.source_pointer)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_candidate_i BEFORE INSERT ON character_lore_reuse_candidate WHEN EXISTS(SELECT 1 FROM character_lore_reuse_candidate WHERE id=NEW.id OR(relation_id=NEW.relation_id AND target_source_path=NEW.target_source_path AND target_pointer=NEW.target_pointer AND target_occurrence_id=NEW.target_occurrence_id)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_slot_i BEFORE INSERT ON character_lore_slot WHEN EXISTS(SELECT 1 FROM character_lore_slot WHERE id=NEW.id OR(row_id=NEW.row_id AND field=NEW.field AND locale=NEW.locale)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_text_i BEFORE INSERT ON character_lore_text WHEN EXISTS(SELECT 1 FROM character_lore_text WHERE id=NEW.id OR(slot_id=NEW.slot_id AND source_path=NEW.source_path AND pair_ordinal=NEW.pair_ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_relation_i BEFORE INSERT ON character_lore_relation WHEN EXISTS(SELECT 1 FROM character_lore_relation WHERE id=NEW.id OR(row_id=NEW.row_id AND kind=NEW.kind AND source_pointer=NEW.source_pointer)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_candidate_i BEFORE INSERT ON character_lore_candidate WHEN EXISTS(SELECT 1 FROM character_lore_candidate WHERE id=NEW.id OR(relation_id=NEW.relation_id AND target_source_path=NEW.target_source_path AND target_pointer=NEW.target_pointer AND target_occurrence_id=NEW.target_occurrence_id)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_navigation_anchor_i BEFORE INSERT ON character_lore_navigation_anchor WHEN EXISTS(SELECT 1 FROM character_lore_navigation_anchor WHERE id=NEW.id OR(source_path=NEW.source_path AND source_pointer=NEW.source_pointer)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_navigation_edge_i BEFORE INSERT ON character_lore_navigation_edge WHEN EXISTS(SELECT 1 FROM character_lore_navigation_edge WHERE id=NEW.id OR(anchor_id=NEW.anchor_id AND kind=NEW.kind AND target_family=NEW.target_family AND target_run=NEW.target_run AND target_occurrence_id=NEW.target_occurrence_id AND source_relation_id=NEW.source_relation_id)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_release_i BEFORE INSERT ON character_lore_release WHEN EXISTS(SELECT 1 FROM character_lore_release) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_row_u BEFORE UPDATE ON character_lore_row BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_row_d BEFORE DELETE ON character_lore_row BEGIN SELECT RAISE(ABORT,'immutable');END;
