CREATE TRIGGER character_lore_reuse_d BEFORE DELETE ON character_lore_reuse BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_slot_u BEFORE UPDATE ON character_lore_reuse_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_slot_d BEFORE DELETE ON character_lore_reuse_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_relation_u BEFORE UPDATE ON character_lore_reuse_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_relation_d BEFORE DELETE ON character_lore_reuse_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_candidate_u BEFORE UPDATE ON character_lore_reuse_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_reuse_candidate_d BEFORE DELETE ON character_lore_reuse_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_slot_u BEFORE UPDATE ON character_lore_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_slot_d BEFORE DELETE ON character_lore_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_text_u BEFORE UPDATE ON character_lore_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_text_d BEFORE DELETE ON character_lore_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_relation_u BEFORE UPDATE ON character_lore_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_relation_d BEFORE DELETE ON character_lore_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_candidate_u BEFORE UPDATE ON character_lore_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_candidate_d BEFORE DELETE ON character_lore_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_navigation_anchor_u BEFORE UPDATE ON character_lore_navigation_anchor BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_navigation_anchor_d BEFORE DELETE ON character_lore_navigation_anchor BEGIN SELECT RAISE(ABORT,'immutable');END;
