CREATE TRIGGER character_lore_navigation_edge_d BEFORE DELETE ON character_lore_navigation_edge BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER character_lore_release_u BEFORE UPDATE ON character_lore_release BEGIN SELECT RAISE(ABORT,'immutable');END;
